func (s *Store) DeactivatePatient(actor Actor, patientID ID) error {
	if !actor.valid() || !actor.IsInternal() {
		return ErrAccessDenied
	}
	return s.mutate(func(snap *snapshot) error {
		p, err := requirePatient(snap, patientID)
		if err != nil {
