			return fmt.Errorf("%w: authorization %q belongs to patient %q, not %q",
				ErrMismatchedPatient, authorizationID, a.PatientID, patientID)
		}
		if a.RevokedAt != nil {
			// 幂等：正式保存的授权已经撤回。确认已有结果即可——保持首次撤回
